def ingest_email_thread(sender: str, subject: str, body: str):
    # Mine facts and preserve sender identity
    result = client.memories.create(
        content=f"Email from {sender}: Subject '{subject}'. Content: {body}",
        tags=["email", "customer-inquiry", "ops"],
        metadata={"sender": sender, "subject": subject}
    )
