import { Agent } from '@mastra/core';
import { PiyAPIClient } from '@piyapi/sdk';

const piyapi = new PiyAPIClient({ apiKey: process.env.PIYAPI_API_KEY });

export const supportAgent = new Agent({
  name: 'SupportCompanion',
  instructions: 'Resolve customer tickets while recalling past user interactions and preferences.',
  model: { provider: 'OPEN_AI', name: 'gpt-4o' },
  tools: {
    queryMemory: {
      description: 'Search customer past context',
      execute: async ({ userId, query }) => {
        return await piyapi.memories.search({ query, userId, limit: 3 });
      }
    }
  }
});

from piyapi_memory import PiyAPIClient

client = PiyAPIClient(api_key="sk_live_prod_key_here")

def store_visual_memory(image_url: str, scene_description: str, tags: list):
    return client.memories.create(
        content=f"Visual asset ({image_url}): {scene_description}",
        tags=["multimodal", "visual-memory"] + tags,
        metadata={"image_url": image_url, "type": "image_descriptor"}
    )
